  --sidebar-accent-foreground: hsl(222 47% 11%);
  --sidebar-border: hsl(240 6% 90%);
  --sidebar-ring: hsl(239 84% 67%);

  /* Custom tokens */
  --success: hsl(142 76% 36%);
  --success-foreground: hsl(0 0% 100%);
  --warning: hsl(43 96% 56%);
